const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountFuji = ee.Geometry.Point([138.7274, 35.3606]).buffer(5000); // 5km buffer
  const dec2019 = ['2019-12-01', '2019-12-31'];
  const dec2020 = ['2020-12-01', '2020-12-31'];

  // 2. Data Acquisition - Landsat 8 Surface Reflectance
  const getL8Collection = (dateRange) => {
    return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(mountFuji)
      .filterDate(dateRange[0], dateRange[1])
      .filter(ee.Filter.lt('CLOUD_COVER', 80));
  };

  const col2019 = getL8Collection(dec2019);
  const col2020 = getL8Collection(dec2020);

  // Check collection sizes
  const size2019 = col2019.size().getInfo();
  const size2020 = col2020.size().getInfo();

  console.log(`2019 Images: ${size2019}, 2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate NDSI and composite
  const calculateNDSI = (image) => {
    // Landsat 8: Green = B3, SWIR = B6
    const ndsi = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('NDSI');

    // Cloud masking using QA_PIXEL band
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4)); // Cloud and cloud shadow
    return image.addBands(ndsi).updateMask(cloudMask.eq(0));
  };

  // Create median composites
  const composite2019 = col2019.map(calculateNDSI).median();
  const composite2020 = col2020.map(calculateNDSI).median();

  // 4. Calculate mean NDSI values
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2019 = composite2019.select('NDSI').reduceRegion({
    reducer: reducer,
    geometry: mountFuji,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = composite2020.select('NDSI').reduceRegion({
    reducer: reducer,
    geometry: mountFuji,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const mean2019 = stats2019.NDSI_mean;
  const mean2020 = stats2020.NDSI_mean;
  const count2019 = stats2019.NDSI_count;
  const count2020 = stats2020.NDSI_count;

  console.log(`2019 Mean NDSI: ${mean2019?.toFixed(3)}, Pixels: ${count2019}`);
  console.log(`2020 Mean NDSI: ${mean2020?.toFixed(3)}, Pixels: ${count2020}`);

  // 5. Validation & Final Answer
  if (count2019 === 0 || count2020 === 0) {
    console.log("<answer>C2</answer>");
  } else if (mean2019 === null || mean2020 === null || 
             Math.abs(mean2019) > 1 || Math.abs(mean2020) > 1) {
    console.log("<answer>C3</answer>");
  } else if (mean2020 < mean2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
